 switch(b.id){case 'review-compare':document.getElementById('compare-panel')?.scrollIntoView({behavior:'smooth',block:'start'});break;case 'load-more':ui.limit+=24;results();break;case 'clear-compare':ui.compare=[];results();break;case 'photos-only':ui.photoOnly=!ui.photoOnly;ui.limit=24;render();break;case 'visited-only':ui.visitedOnly=!ui.visitedOnly;ui.unvisited=false;ui.limit=24;render();break;case 'unvisited-only':ui.visitedOnly=false;ui.unvisited=!ui.unvisited;ui.limit=24;render();break;case 'optimize-trip':if(state.trip.length<2){toast('Add at least two stops to suggest an order.');break}if(optimizeTrip()){render();toast('Stops ordered by nearest geographic neighbour. Check the road route before leaving.')}else toast('Coordinates are needed to suggest a stop order.');break;case 'close-detail':dialog.close();break;case 'saved-only':ui.savedOnly=!ui.savedOnly;render();break;case 'view-toggle':ui.view=ui.view==='grid'?'map':'grid';render();break;case 'clear-filters':Object.assign(ui,{category:'All',query:'',district:'All',distance:0,budget:0,sort:'curated',savedOnly:false,photoOnly:false,unvisited:false,visitedOnly:false,limit:24});render();break;case 'open-saved':ui.savedOnly=true;navigate('explore');break;case 'save-note':state.notes[activeDetail]=document.getElementById('field-note').value;save();toast('Field note saved.');break;case 'remove-target':delete state.targets[activeDetail];save();refresh();break;case 'remove-visit':delete state.visited[activeDetail];save();refresh();toast('Stamp removed.');break;case 'reset-distance':delete state.routeOverrides[activeDetail];save();refresh();break;case 'export-backup':download('avara-pro-passport.json',JSON.stringify({format:'avara-pro-v1',...state},null,2));toast('Passport backup downloaded.');break;case 'export-trip':{const c=tripCost();download('avara-pro-journey.txt',`AVARA PRO — YOUR JOURNEY\n\nCuttack → ${state.trip.map(id=>byId(id).name).join(' → ')} → Cuttack\n\n${state.tripConfig.days} days / ${state.tripConfig.nights} nights\nEstimated round trip: ${c.distance} km\nTravel time with buffer: ${time(c.time)}\nFuel: ${money(c.f)}\nFood: ${money(c.food)}\nStay: ${money(c.stay)}\nActivities: ${money(c.activities)}\nContingency: ${money(c.contingency)}\nPlanning total: ${money(c.total)}\n\nASSUMPTIONS\nClassic 350; ${state.settings.mileage} km/l; ₹${state.settings.fuel}/litre; ${state.settings.speed} km/h; ${state.settings.buffer}% time buffer.\nDistance ${state.tripConfig.km?'entered by you':'estimated from geographic coordinates'}. Not live routing or price quotes. Check entry rules, closures, fees and roads before departure.\n\nRoute: ${multiRouteUrl()}`,'text/plain');break}}
