 document.addEventListener('submit',e=>{if(!['quick-visit','finder','settings-form','trip-config','goal-form','visit-form','route-override','target-form'].includes(e.target.id))return;e.preventDefault();const f=new FormData(e.target);switch(e.target.id){case 'quick-visit':{const date=String(f.get('date'));try{markVisited(visitCandidate,date)}catch(err){toast(err.message);return}visitDialog.close();refresh();toast('Stamp collected ✳ Find it in Passport. Edit or remove it in place details.');break}case 'target-form':state.targets[activeDetail]=Number(f.get('year'));if(!state.saved.includes(activeDetail))state.saved.push(activeDetail);save();refresh();toast('Added to your yearly someday list.');break;case 'finder':ui.category=f.get('category');ui.distance=Number(f.get('distance'));ui.scope='odisha';ui.district='All';ui.query='';navigate('explore');break;case 'settings-form':for(const k of Object.keys(state.settings))state.settings[k]=Number(f.get(k));save();toast('Your ride defaults are saved.');render();break;case 'trip-config':const nextConfig={days:Number(f.get('days')),nights:Number(f.get('nights')),km:Number(f.get('km'))};if(nextConfig.nights>=nextConfig.days){toast('Use fewer nights than days.');return}state.tripConfig=nextConfig;save();render();break;case 'goal-form':state.goal=Number(f.get('goal'));state.goalYear=Number(f.get('year'));save();render();toast('Your intention is set.');break;case 'visit-form':{const date=String(f.get('date'));try{markVisited(activeDetail,date)}catch(err){toast(err.message);return}refresh();toast('Another memory, another stamp. ✳');break}case 'route-override':state.routeOverrides[activeDetail]=Number(f.get('km'));save();refresh();toast('Fuel and time updated with your distance.');break}});
 document.addEventListener('input',e=>{if(e.target.id==='stamp-search'){ui.passportQuery=e.target.value;document.getElementById('stamp-board').innerHTML=window.renderAvaraStamps({state,places,ui,esc});return}if(e.target.id==='search'){ui.query=e.target.value;ui.limit=24;results()}});
 document.addEventListener('change',async e=>{if(e.target.dataset.passportFilter){ui[e.target.dataset.passportFilter]=e.target.value;render();return}if(e.target.dataset.filter){const k=e.target.dataset.filter;ui.limit=24;ui[k]=['distance','budget'].includes(k)?Number(e.target.value):e.target.value;results()}if(e.target.dataset.check!==undefined){state.checklist[e.target.dataset.check]=e.target.checked;save()}if(e.target.id==='import-backup'){try{const file=e.target.files[0];if(!file)return;if(file.size>2000000)throw new Error('This file is too large.');const data=JSON.parse(await file.text());if(data.format!=='avara-pro-v1'||!Array.isArray(data.saved)||!data.visited||!data.notes)throw new Error('Choose an Avara Pro passport backup.');if(window.AvaraJournal&&Array.isArray(data.calendarPlans))state.calendarPlans=[...new Map([...(state.calendarPlans||[]),...window.AvaraJournal.validatePlans(data.calendarPlans)].map(p=>[p.id,p])).values()].slice(0,100);state.saved=[...new Set([...state.saved,...data.saved.filter(id=>byId(id)).map(canonicalId)])];for(const [id,year] of Object.entries(data.targets||{}))if(byId(id)&&Number.isInteger(year)&&year>=2000&&year<=2100)state.targets[canonicalId(id)]=year;for(const [id,v]of Object.entries(data.visited)){if(byId(id)&&v&&typeof v.date==='string'&&validVisitDate(v.date))state.visited[canonicalId(id)]={date:v.date}}for(const [id,note]of Object.entries(data.notes))if(byId(id)&&typeof note==='string')state.notes[canonicalId(id)]=note.slice(0,5000);save();render();toast('Your passport memories have been merged.')}catch(err){toast(err.message||'Could not import this backup.')}}});
